import json, subprocess, sys
MAIN = "/app/submission/main.py"
def ok(name, cfg):
    p = subprocess.run([sys.executable, "-I", MAIN, "compile"],
                       input=json.dumps(cfg).encode(), stdout=subprocess.PIPE)
    good = p.returncode == 0 and json.loads(p.stdout) and "error" not in json.loads(p.stdout)
    print(("PASS " if good else "FAIL ") + name, "" if good else (p.returncode, p.stdout[:100]))

ok("no rules", {"version":1,"idle_timeout":0,"packet_limit":1,"prefix_width":1,"rules":[],"fallback":{"class":0}})
ok("max W", {"version":1,"idle_timeout":10**9,"packet_limit":10**9,"prefix_width":32,"rules":[],"fallback":{"feature":31,"threshold":2048,"le":{"class":1},"gt":{"class":2}}})
ok("identical ranges", {"version":1,"idle_timeout":1,"packet_limit":1,"prefix_width":1,
  "rules":[{"id":5,"class":1,"priority":0,"ranges":[[0,0]]},{"id":5+1,"class":2,"priority":0,"ranges":[[0,0]]}],
  "fallback":{"class":3}})
ok("2048 rules 16384 pos", {"version":1,"idle_timeout":0,"packet_limit":10**9,"prefix_width":32,
  "rules":[{"id":i,"class":i%65536,"priority":i,"ranges":[[i%2048-1024, i%2048-1023]]*8} for i in range(2048)],
  "fallback":{"class":1}})
def depth16():
    # leaf exactly at depth 16
    nd = {"class": 1}
    for _ in range(16):
        nd = {"feature": 0, "threshold": 0, "le": nd, "gt": {"class": 2}}
    return nd
ok("depth 16", {"version":1,"idle_timeout":1,"packet_limit":1,"prefix_width":1,"rules":[],"fallback":depth16()})
def nodes255():
    # 255 total nodes: 127 internal + 128 leaves (perfect tree depth 7)
    def build(h):
        if h == 0:
            return {"class": 1}
        return {"feature": 0, "threshold": 0, "le": build(h-1), "gt": build(h-1)}
    return build(7)
ok("255 nodes", {"version":1,"idle_timeout":1,"packet_limit":1,"prefix_width":1,"rules":[],"fallback":nodes255()})
ok("extremes", {"version":1,"idle_timeout":0,"packet_limit":1,"prefix_width":2,
